import { save, update } from "@/api/treeManager/cmdbres";
import IconChoose from "@/components/iconChoose/index.vue";
export default {
  name: "CmdbResAddEdit",
  components: {
    IconChoose: IconChoose
  },
  props: ['fromValue', 'isShow', 'type'],
  data: function data() {
    return {
      submitParams: {},
      rules: {
        ciId: [{
          required: true,
          message: '模型ID不能为空',
          trigger: 'blur'
        }],
        ciLabel: [{
          required: true,
          message: '模型中文名不能为空',
          trigger: 'blur'
        }],
        ciName: [{
          required: true,
          message: '模型英文名不能为空',
          trigger: 'blur'
        }],
        selectCiId: [{
          required: true,
          message: '查询模型ID不能为空',
          trigger: 'blur'
        }],
        selectCiName: [{
          required: true,
          message: '查询模型英文名不能为空',
          trigger: 'blur'
        }]
      },
      saveLoading: false,
      yesNoList: null,
      showIconChoose: false
    };
  },
  mounted: function mounted() {
    if (this.type == 'edit') {
      this.submitParams = JSON.parse(JSON.stringify(this.fromValue));
    }
    this.initDict();
  },
  methods: {
    initDict: function initDict() {
      this.yesNoList = [{
        name: '是',
        code: 1
      }, {
        name: '否',
        code: 0
      }];
    },
    submit: function submit() {
      var _this = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          if (_this.type == 'add') {
            _this.saveLoading = true;
            save(_this.submitParams).then(function (res) {
              _this.saveLoading = false;
              _this.$message.success('添加成功');
              _this.$emit("close");
              _this.$emit("refreshData");
            });
          } else if (_this.type == 'edit') {
            _this.saveLoading = true;
            update(_this.submitParams).then(function (res) {
              _this.saveLoading = false;
              _this.$message.success('修改成功');
              _this.$emit("close");
              _this.$emit("refreshData");
            });
          }
        }
      });
    },
    iconClick: function iconClick() {
      this.showIconChoose = true;
    },
    chooseClick: function chooseClick(arg) {
      this.submitParams.ciIcon = arg.icon;
    },
    iconClear: function iconClear() {
      this.$forceUpdate();
    },
    getTitle: function getTitle(type) {
      if (type == 'add') {
        return '新 增';
      } else if (type == 'edit') {
        return '更 新';
      }
      return null;
    }
  }
};
